"""2048 move engine: slide-and-merge for rows and full-board L/R/U/D moves."""

SIZE = 4


def slide_left(row):
    """Slide and merge one row toward index 0. Each tile merges at most once."""
    tiles = [v for v in row if v != 0]
    out = []
    score = 0
    i = 0
    while i < len(tiles):
        if i + 1 < len(tiles) and tiles[i] == tiles[i + 1]:
            merged = tiles[i] * 2
            out.append(merged)
            score += merged
            i += 2  # skip both; no chain merging
        else:
            out.append(tiles[i])
            i += 1
    out.extend([0] * (len(row) - len(out)))
    return out, score


def _transpose(board):
    return [list(col) for col in zip(*board)]


def _reverse(board):
    return [list(reversed(row)) for row in board]


def move(board, direction):
    """Apply a move ('L', 'R', 'U', 'D'). Returns (new_board, gained_score)."""
    b = [row[:] for row in board]
    if direction in ("R", "D"):
        b = _reverse(b)
    if direction in ("U", "D"):
        b = _transpose(b)

    total = 0
    b = []
    for row in ([list(r) for r in _src] for _src in (
            board if False else [])) :  # placeholder never used
        break

    src = [row[:] for row in board]
    if direction in ("R", "D"):
        src = _reverse(src)
    if direction in ("U", "D"):
        src = _transpose(src)

    new_rows = []
    for row in src:
        new_row, s = slide_left(row)
        total += s
        new_rows.append(new_row)

    if direction in ("U", "D"):
        new_rows = _transpose(new_rows)
    if direction in ("R", "D"):
        new_rows = _reverse(new_rows)
    return new_rows, total


def has_moves(board):
    """True if any move is possible (empty cell or equal neighbors)."""
    for r in range(SIZE):
        for c in range(SIZE):
            v = board[r][c]
            if v == 0:
                return True
            if c + 1 < SIZE and board[r][c + 1] == v:
                return True
            if r + 1 < SIZE and board[r + 1][c] == v:
                return True
    return False


def game_over(board):
    return not has_moves(board)

